#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
# ⚠ DO NOT REMOVE — Scope: §DICT-CENSUS stage 3 (bim-compiler prompts/ERP_DEPTH_FILM.md). Closes dictionary-table gaps the census found, for the LOOKUP / LEAF tables only
#   (messages, print formats, import formats, info windows, forms, ...). EXTRACT ONLY from the pilot (idempiere_pilot = the oracle), client 0/11. Emits `INSERT OR IGNORE` for
#   exactly the rows whose primary key the seed-as-loaded (ad_seed.db + the patch WITHOUT this block) lacks, using the seed table's own columns. The block between
#   `-- >>> G-DICT` / `-- <<< G-DICT` of erp/patches/ad_seed.db.sql is replaced in place. Tables behind windows/modules the twin deliberately does not carry
#   (AD-LAYER LAW 6: replication, web store, CM, ...) are NOT here - the census names them, never fakes them. READ the printed row counts.
import json, os, re, sqlite3, subprocess

HERE = os.path.dirname(os.path.abspath(__file__)); ERP = os.path.dirname(HERE)
TABLES = os.environ.get('G_DICT_TABLES', 'ad_task ad_task_access ad_form_access ad_process_access ad_workflow_access ad_infowindow_access ad_document_action_access ad_message ad_printformat ad_printformatitem ad_form ad_sysconfig ad_image r_mailtext ad_impformat ad_impformat_row ad_ref_list ad_infowindow ad_infocolumn ad_toolbarbutton ad_toolbarbuttonrestrict').split()   # + §18 (bim-compiler ERP_FRIENDLY_OPS_LENS.md): window/tab toolbar buttons (MToolBarButton), absent from the seed

DDL_ONLY = os.environ.get('G_DICT_DDL', 'c_cash c_cashline m_movementlinema r_requestupdates ad_session ad_pinstance ad_pinstance_para').split()   # §UDP-2: ad_pinstance(_para) hold the process dialog's Saved Parameters + Last Run (written through the signed op-log). tables the legacy views read that the seed lacks: structure only (the twin gains rows when its own flows write them)


def pg(sql):
    r = subprocess.run(['docker', 'exec', '-i', 'postgres', 'psql', '-U', 'postgres', '-d', os.environ.get('PG_DB', 'idempiere_pilot'), '-tA', '-c', 'set search_path=adempiere;' + sql],
                       capture_output=True, text=True, check=True)
    return [l for l in r.stdout.split('\n') if l and l != 'SET']   # row_to_json output is one line per row (newlines are escaped)


def lit(v):   # no raw newlines in the output: the loader splits statements on ";\s*\n", a text value containing that would be cut in two
    if v is None: return 'NULL'
    q = lambda x: "'" + x.replace("'", "''") + "'"
    return '||'.join({'\n': 'char(10)', '\r': 'char(13)'}.get(p) or q(p) for p in re.split(r'(\n|\r)', str(v)) if p != '') or "''"


patch_path = os.path.join(HERE, 'ad_seed.db.sql'); patch = open(patch_path).read()
base_patch = re.sub(r'-- >>> G-DICT.*?-- <<< G-DICT\n?', '', patch, flags=re.S)
db = sqlite3.connect(':memory:'); sqlite3.connect(os.path.join(ERP, 'ad_seed.db')).backup(db)
for st in re.split(r';\s*\n', base_patch):
    st = re.sub(r'^\s*--[^\n]*\n?', '', st, flags=re.M).strip()
    if st:
        try: db.execute(st)
        except Exception: pass
out = ['-- >>> G-DICT (generated by erp/patches/build_dict_patch.py from the pilot; lookup/leaf dictionary tables, only rows the seed lacks)']
total = 0
for t in TABLES:
    info = list(db.execute('pragma table_info(%s)' % t)); scols = [r[1].lower() for r in info]
    if not scols:   # absent in the seed (ad_task, ad_task_access): DDL + primary key from the live schema
        cs = pg("select column_name || ' ' || case when data_type in ('numeric','integer','bigint') then 'NUMERIC' else 'TEXT' end from information_schema.columns where table_schema='adempiere' and table_name='%s' order by ordinal_position" % t)
        pkc = pg("select kcu.column_name from information_schema.table_constraints tc join information_schema.key_column_usage kcu using (constraint_name, table_schema) where tc.table_schema='adempiere' and tc.table_name='%s' and tc.constraint_type='PRIMARY KEY' order by kcu.ordinal_position" % t)
        ddl = 'CREATE TABLE IF NOT EXISTS %s (%s%s);' % (t, ', '.join(cs), (', PRIMARY KEY (%s)' % ', '.join(pkc)) if pkc else ''); out.append(ddl); db.execute(ddl.rstrip(';'))
        info = list(db.execute('pragma table_info(%s)' % t)); scols = [r[1].lower() for r in info]
    pk = [r[1].lower() for r in sorted(info, key=lambda r: r[5]) if r[5] > 0] or ([t + '_id'] if t + '_id' in scols else [])
    if not pk: print('§G-DICT %s SKIP (no primary key in the seed table)' % t); continue
    pcols = set(pg("select column_name from information_schema.columns where table_schema='adempiere' and table_name='%s'" % t))
    cols = [c for c in scols if c in pcols]
    where = ' where ad_client_id in (0,11)' if 'ad_client_id' in cols else ''
    have = set(tuple(str(x) for x in r) for r in db.execute('select %s from %s' % (','.join(pk), t)))
    sel = ', '.join('%s::text as %s' % (c, c) for c in cols)
    legacy = [json.loads(l) for l in pg('select row_to_json(x)::text from (select %s from %s%s) x' % (sel, t, where))]
    miss = [r for r in legacy if tuple(str(r[c]) for c in pk) not in have]; n = len(miss)
    for i in range(0, n, 100):   # multi-row VALUES: the column list is written once per 100 rows (patch size + statement count)
        out.append('INSERT OR IGNORE INTO %s (%s) VALUES %s;' % (t, ','.join(cols), ',\n'.join('(' + ','.join(lit(r[c]) for c in cols) + ')' for r in miss[i:i + 100])))
    total += n
    print('§G-DICT %s legacy=%d seed-has=%d emitted=%d dropped-cols=%s' % (t, len(legacy), len(legacy) - n, n, sorted(pcols - set(cols))))
for t in DDL_ONLY:
    if list(db.execute('pragma table_info(%s)' % t)): continue
    cs = pg("select column_name || ' ' || case when data_type in ('numeric','integer','bigint') then 'NUMERIC' else 'TEXT' end from information_schema.columns where table_schema='adempiere' and table_name='%s' order by ordinal_position" % t)
    pkc = pg("select kcu.column_name from information_schema.table_constraints tc join information_schema.key_column_usage kcu using (constraint_name, table_schema) where tc.table_schema='adempiere' and tc.table_name='%s' and tc.constraint_type='PRIMARY KEY' order by kcu.ordinal_position" % t)
    if not cs: print('§G-DICT %s DDL-SKIP (absent on the pilot)' % t); continue
    out.append('CREATE TABLE IF NOT EXISTS %s (%s%s);' % (t, ', '.join(cs), (', PRIMARY KEY (%s)' % ', '.join(pkc)) if pkc else '')); print('§G-DICT %s DDL (%d columns, pk=%s)' % (t, len(cs), pkc))
# fact_acct column parity (§DICT-CENSUS column census 2026-10-15: the twin kept 34 of the legacy 57 columns, every other core transaction table is 100%). model_post.js already hands dateacct/datetrx/dimensions
#   to ML.newPO, which DROPS keys the table lacks - adding the columns lets the existing poster fill them. ADD COLUMN has no IF NOT EXISTS: a re-apply fails per column and the loader counts it (tolerated, idempotent in effect).
for t in os.environ.get('G_DICT_ALTER', 'fact_acct').split():
    have_cols = set(r[1].lower() for r in db.execute('pragma table_info(%s)' % t))
    for r in pg("select column_name || '|' || case when data_type in ('numeric','integer','bigint') then 'NUMERIC' else 'TEXT' end from information_schema.columns where table_schema='adempiere' and table_name='%s' order by ordinal_position" % t):
        c, ty = r.split('|')
        if c not in have_cols: out.append('ALTER TABLE %s ADD COLUMN %s %s;' % (t, c, ty))
BACKFILL = [  # (AD_Table_ID, document table, key, dateacct expr, datetrx expr) - the Doc.getDateAcct()/getDateDoc() the poster uses; checked against the pilot (0 mismatches except re-dated docs)
    (318, 'c_invoice', 'c_invoice_id', 'dateacct', 'dateinvoiced'), (319, 'm_inout', 'm_inout_id', 'dateacct', 'movementdate'), (335, 'c_payment', 'c_payment_id', 'dateacct', 'datetrx'),
    (735, 'c_allocationhdr', 'c_allocationhdr_id', 'dateacct', 'datetrx'), (323, 'm_movement', 'm_movement_id', 'movementdate', 'movementdate'), (224, 'gl_journal', 'gl_journal_id', 'dateacct', 'datedoc'),
    (472, 'm_matchinv', 'm_matchinv_id', 'dateacct', 'datetrx'), (392, 'c_bankstatement', 'c_bankstatement_id', 'statementdate', 'statementdate')]
if any(r[1].lower() == 'dateacct' for r in db.execute('pragma table_info(fact_acct)')) or True:
    for tid, dt, k, da, dx in BACKFILL:
        if list(db.execute('pragma table_info(%s)' % dt)):
            out.append("UPDATE fact_acct SET dateacct=(SELECT d.%s FROM %s d WHERE d.%s=fact_acct.record_id), datetrx=(SELECT d.%s FROM %s d WHERE d.%s=fact_acct.record_id) WHERE ad_table_id=%d AND dateacct IS NULL;" % (da, dt, k, dx, dt, k, tid))
out.append('-- <<< G-DICT')
blk = '\n'.join(out) + '\n'
new = re.sub(r'-- >>> G-DICT.*?-- <<< G-DICT\n?', lambda m: blk, patch, flags=re.S) if '-- >>> G-DICT' in patch else patch.rstrip('\n') + '\n' + blk
open(patch_path, 'w').write(new)
print('§G-DICT-TOTAL statements=%d' % total)
